      function seed(even) { particles = Array.from({length:96}, function (_, i) { return {x: even ? (i < 48 ? .04 + Math.random() * .43 : .53 + Math.random() * .43) : .04 + Math.random() * .42, y:.1 + Math.random() * .8, a:Math.random() * Math.PI * 2}; }); }
